// Golden diagnostics were captured from the actual frozen REA 6.8.0 public MCP
// endpoint, with every request/response bound to its original wire ID and bytes.
// Original goldens SHA256 b0836938d02384c5076eb8cdd1c50d61591f8a47cd1931c82d486b38d6b1f94c.
// Original wire SHA256 68429cddb2603d27b7c1351ebc0e8a741362c10400ea04a2d39cbfe6e38863ab.
// Node binary SHA256 94efd062ed066c1a0b332e18249859c905e920eeada5df55d24c99b919629a90.
// The fixture is a lossless projection of input, JS Object.keys and the one
// varying diagnostic string. All other error fields are the verified common
// template. Schema-valid cases reached the original file service; they are not
// claims that the nonexistent selected APK parsed successfully.
use super::*;

#[test]
fn all_actual_public_mcp_input_goldens_match() {
	let fixture: Value = serde_json::from_str(GOLDENS).unwrap();
	let rows = fixture["rows"].as_array().unwrap();
	assert_eq!(rows.len(), 297);
	let mut counts = (0, 0);
	for row in rows {
		let name = row[0].as_str().unwrap();
		let keys: Vec<String> = serde_json::from_value(row[2].clone()).unwrap();
		let view_keys: Option<Vec<String>> = serde_json::from_value(row[3].clone()).unwrap();
		let observed = validate(&row[1], Some(&keys), view_keys.as_deref());
		if row[4].is_null() {
			assert!(
				observed.is_ok(),
				"{name}: schema-valid input rejected: {observed:?}"
			);
			counts.0 += 1;
		} else {
			let mut expected = fixture["template"].clone();
			expected["details"]["issues"][0]["message"] = row[4].clone();
			match observed {
				Ok(()) => panic!("{name}: schema-invalid input accepted"),
				Err(failure) => {
					assert_eq!(failure.0, expected, "{name}: public MCP diagnostic differs")
				}
			}
			counts.1 += 1;
		}
	}
	assert_eq!(counts, (56, 241));
}

#[test]
fn incomplete_or_repeated_order_hints_cannot_authorize_unknown_keys() {
	let args = json!({"path":"/fixture.apk","aaa":1,"zzz":2,
        "view":{"collection":"signers","aaa":1,"zzz":2}});
	let keys = vec!["path".into(), "zzz".into(), "zzz".into()];
	let view_keys = vec!["collection".into(), "zzz".into()];
	let error = validate(&args, Some(&keys), Some(&view_keys)).unwrap_err();
	assert_eq!(
		error.0["details"]["issues"][0]["message"],
		"view: Unrecognized keys: \"zzz\", \"aaa\", Unrecognized keys: \"zzz\", \"aaa\""
	);
}

